conv2d_cuda_src = r"""
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <c10/cuda/CUDAStream.h>

#include <cute/tensor.hpp>

using namespace cute;

// Cooperative tiled 2D convolution (stride=1, dilation=1) using CuTe tensors.
// Each block computes a TH x TW output tile for OC_C output channels,
// looping over input channels in chunks of IC_C with a shared-memory
// input tile (including the K-1 halo) and shared-memory weights.
template <int K, typename T>
__global__ void conv2d_cute_kernel(
    const T* __restrict__ X,
    const T* __restrict__ Wt,
    const T* __restrict__ B,
    T* __restrict__ Y,
    int N, int C, int H, int W,
    int OC, int Hout, int Wout,
    int pad)
{
  constexpr int Threads = 256;
  constexpr int TH      = 16;
  constexpr int TW      = 64;
  constexpr int IC_C    = 4;
  constexpr int OC_C    = 8;
  constexpr int SH      = TH + K - 1;   // shared tile height (with halo)
  constexpr int SW      = TW + K - 1;   // shared tile width  (with halo)
  constexpr int PVec    = TH * TW / Threads;  // output pixels per thread (=4)

  const int tid     = threadIdx.x;
  const int n       = blockIdx.z;
  const int oc_base = blockIdx.y * OC_C;

  const int tiles_w = (Wout + TW - 1) / TW;
  const int tile    = blockIdx.x;
  const int tile_h  = tile / tiles_w;
  const int tile_w  = tile - tile_h * tiles_w;
  const int oh0     = tile_h * TH;
  const int ow0     = tile_w * TW;
  const int ih0     = oh0 - pad;
  const int iw0     = ow0 - pad;

  // Global tensors described with CuTe layouts
  Tensor mX = make_tensor(make_gmem_ptr(X + (int64_t)n * C * H * W),
                          make_shape(C, H, W),
                          make_stride((int64_t)H * W, (int64_t)W, Int<1>{}));

  Tensor mW = make_tensor(make_gmem_ptr(Wt),
                          make_shape(OC, C, Int<K>{}, Int<K>{}),
                          make_stride((int64_t)C * K * K, (int64_t)K * K,
                                      Int<K>{}, Int<1>{}));

  Tensor mY = make_tensor(make_gmem_ptr(Y + (int64_t)n * OC * Hout * Wout),
                          make_shape(OC, Hout, Wout),
                          make_stride((int64_t)Hout * Wout, (int64_t)Wout, Int<1>{}));

  // Shared memory tiles
  __shared__ T sX_raw[IC_C * SH * SW];
  __shared__ T sW_raw[OC_C * IC_C * K * K];

  Tensor sX = make_tensor(make_smem_ptr(sX_raw),
                          make_shape(Int<IC_C>{}, Int<SH>{}, Int<SW>{}),
                          make_stride(Int<SH * SW>{}, Int<SW>{}, Int<1>{}));

  Tensor sW = make_tensor(make_smem_ptr(sW_raw),
                          make_shape(Int<OC_C>{}, Int<IC_C>{}, Int<K>{}, Int<K>{}),
                          make_stride(Int<IC_C * K * K>{}, Int<K * K>{},
                                      Int<K>{}, Int<1>{}));

  // Output pixel coordinates handled by this thread (thread-contiguous quarters of the tile)
  int  ph[PVec], pw[PVec];
  bool pv[PVec];
  #pragma unroll
  for (int i = 0; i < PVec; ++i) {
    int p  = i * Threads + tid;
    int r  = p / TW;
    int c  = p - r * TW;
    ph[i]  = r;
    pw[i]  = c;
    pv[i]  = ((oh0 + r) < Hout) && ((ow0 + c) < Wout);
  }

  // Accumulators, initialized with bias (if any)
  T acc[OC_C][PVec];
  #pragma unroll
  for (int o = 0; o < OC_C; ++o) {
    int oc  = oc_base + o;
    T bval  = T(0);
    if (B != nullptr && oc < OC) bval = B[oc];
    #pragma unroll
    for (int i = 0; i < PVec; ++i) acc[o][i] = bval;
  }

  for (int ic0 = 0; ic0 < C; ic0 += IC_C) {
    // Cooperatively load the weight chunk (OC_C x IC_C x K x K)
    constexpr int WSize = OC_C * IC_C * K * K;
    #pragma unroll
    for (int idx = tid; idx < WSize; idx += Threads) {
      int kw = idx % K;
      int kh = (idx / K) % K;
      int ic = (idx / (K * K)) % IC_C;
      int o  = idx / (K * K * IC_C);
      int oc  = oc_base + o;
      int gic = ic0 + ic;
      T v = T(0);
      if (oc < OC && gic < C) v = mW(oc, gic, kh, kw);
      sW(o, ic, kh, kw) = v;
    }

    // Cooperatively load the input tile (IC_C x SH x SW) with zero padding
    constexpr int XSize = IC_C * SH * SW;
    for (int idx = tid; idx < XSize; idx += Threads) {
      int sw = idx % SW;
      int sh = (idx / SW) % SH;
      int ic = idx / (SW * SH);
      int gic = ic0 + ic;
      int ih  = ih0 + sh;
      int iw  = iw0 + sw;
      T v = T(0);
      if (gic < C && (unsigned)ih < (unsigned)H && (unsigned)iw < (unsigned)W) {
        v = mX(gic, ih, iw);
      }
      sX(ic, sh, sw) = v;
    }
    __syncthreads();

    // Compute on the resident tiles
    #pragma unroll
    for (int ic = 0; ic < IC_C; ++ic) {
      if (ic0 + ic >= C) break;
      #pragma unroll
      for (int kh = 0; kh < K; ++kh) {
        #pragma unroll
        for (int kw = 0; kw < K; ++kw) {
          T xv[PVec];
          #pragma unroll
          for (int i = 0; i < PVec; ++i) {
            xv[i] = sX(ic, ph[i] + kh, pw[i] + kw);
          }
          #pragma unroll
          for (int o = 0; o < OC_C; ++o) {
            T wv = sW(o, ic, kh, kw);
            #pragma unroll
            for (int i = 0; i < PVec; ++i) {
              acc[o][i] += xv[i] * wv;
            }
          }
        }
      }
    }
    __syncthreads();
  }

  // Epilogue: write results
  #pragma unroll
  for (int o = 0; o < OC_C; ++o) {
    int oc = oc_base + o;
    if (oc >= OC) continue;
    #pragma unroll
    for (int i = 0; i < PVec; ++i) {
      if (!pv[i]) continue;
      mY(oc, oh0 + ph[i], ow0 + pw[i]) = acc[o][i];
    }
  }
}

namespace {
template <int K>
void conv2d_launch(const float* X, const float* Wt, const float* B, float* Y,
                   int N, int C, int H, int W, int OC, int Hout, int Wout,
                   int pad, cudaStream_t stream)
{
  constexpr int TH   = 16;
  constexpr int TW   = 64;
  constexpr int OC_C = 8;
  dim3 block(256);
  dim3 grid((unsigned)(((Hout + TH - 1) / TH) * ((Wout + TW - 1) / TW)),
            (unsigned)((OC + OC_C - 1) / OC_C),
            (unsigned)N);
  conv2d_cute_kernel<K, float><<<grid, block, 0, stream>>>(
      X, Wt, B, Y, N, C, H, W, OC, Hout, Wout, pad);
}
} // namespace

torch::Tensor conv2d_cute_forward(torch::Tensor x,
                                  torch::Tensor w,
                                  c10::optional<torch::Tensor> b,
                                  int stride, int padding, int dilation)
{
  TORCH_CHECK(x.is_cuda() && w.is_cuda(), "x and w must be CUDA tensors");
  TORCH_CHECK(x.scalar_type() == at::kFloat, "x must be float32");
  TORCH_CHECK(w.scalar_type() == at::kFloat, "w must be float32");
  TORCH_CHECK(x.dim() == 4, "x must be [N, C, H, W]");
  TORCH_CHECK(w.dim() == 4, "w must be [OC, C, K, K]");
  TORCH_CHECK(stride == 1 && dilation == 1,
              "custom CuTe kernel currently supports stride=1, dilation=1");
  TORCH_CHECK(padding >= 0, "padding must be >= 0");

  int64_t N  = x.size(0);
  int64_t C  = x.size(1);
  int64_t H  = x.size(2);
  int64_t W  = x.size(3);
  int64_t OC = w.size(0);
  int64_t K  = w.size(2);
  TORCH_CHECK(w.size(1) == C, "w.size(1) must equal C (groups=1)");
  TORCH_CHECK(w.size(3) == K, "kernel must be square");

  int64_t Hout = (H + 2 * padding - (K - 1) - 1) + 1;  // stride=1, dilation=1
  int64_t Wout = (W + 2 * padding - (K - 1) - 1) + 1;
  TORCH_CHECK(Hout > 0 && Wout > 0, "Invalid output size");

  auto x_c = x.contiguous();
  auto w_c = w.contiguous();

  torch::Tensor b_c;
  const float* b_ptr = nullptr;
  if (b.has_value()) {
    b_c = b.value().contiguous();
    TORCH_CHECK(b_c.is_cuda() && b_c.scalar_type() == at::kFloat,
                "bias must be CUDA float32");
    TORCH_CHECK(b_c.dim() == 1 && b_c.size(0) == OC, "bias must be [OC]");
    b_ptr = b_c.data_ptr<float>();
  }

  auto y = torch::empty({N, OC, Hout, Wout}, x.options());

  cudaStream_t stream = c10::cuda::getCurrentCUDAStream().stream();
  const float* Xp = x_c.data_ptr<float>();
  const float* Wp = w_c.data_ptr<float>();
  float* Yp = y.data_ptr<float>();

  switch ((int)K) {
    case 1: conv2d_launch<1>(Xp, Wp, b_ptr, Yp, (int)N, (int)C, (int)H, (int)W,
                             (int)OC, (int)Hout, (int)Wout, padding, stream); break;
    case 2: conv2d_launch<2>(Xp, Wp, b_ptr, Yp, (int)N, (int)C, (int)H, (int)W,
                             (int)OC, (int)Hout, (int)Wout, padding, stream); break;
    case 3: conv2d_launch<3>(Xp, Wp, b_ptr, Yp, (int)N, (int)C, (int)H, (int)W,
                             (int)OC, (int)Hout, (int)Wout, padding, stream); break;
    case 4: conv2d_launch<4>(Xp, Wp, b_ptr, Yp, (int)N, (int)C, (int)H, (int)W,
                             (int)OC, (int)Hout, (int)Wout, padding, stream); break;
    case 5: conv2d_launch<5>(Xp, Wp, b_ptr, Yp, (int)N, (int)C, (int)H, (int)W,
                             (int)OC, (int)Hout, (int)Wout, padding, stream); break;
    case 6: conv2d_launch<6>(Xp, Wp, b_ptr, Yp, (int)N, (int)C, (int)H, (int)W,
                             (int)OC, (int)Hout, (int)Wout, padding, stream); break;
    case 7: conv2d_launch<7>(Xp, Wp, b_ptr, Yp, (int)N, (int)C, (int)H, (int)W,
                             (int)OC, (int)Hout, (int)Wout, padding, stream); break;
    default:
      TORCH_CHECK(false, "Unsupported kernel_size for custom CuTe conv2d: ", K);
  }

  auto err = cudaGetLastError();
  TORCH_CHECK(err == cudaSuccess, "conv2d_cute_kernel launch failed: ",
              cudaGetErrorString(err));

  return y;
}
"""

conv2d_ext = load_inline(
    name="cute_conv2d_tiled_ext",
    cpp_sources=conv2d_cpp_decl,
    cuda_sources=conv2d_cuda_src,
    functions=["conv2d_cute_forward"],
    extra_cflags=["-O3"],
    extra_cuda_cflags=["-O3"],
    extra_include_paths=[
        "/home/tarasaba/PycharmProjects/cutegen_test/cutegen/cutlass/include",
        "/home/tarasaba/PycharmProjects/cutegen_test/cutegen/cutlass/include/cute/",
    ],
    verbose=False,
)


class ModelNew(nn.Module):
    """
    Standard 2D convolution with a square kernel, computed entirely by a
    single custom cooperative-tiled CUDA kernel written with CuTe.
    """
    def __init__(self, in_channels: int, out_channels: int, kernel_size: int,
                 stride: int = 1, padding: int = 0, dilation: int = 1,
                 groups: int = 1, bias: bool = False):
        super(ModelNew, self).__init__()
        assert groups == 1, "ModelNew supports groups=1 only"
        assert stride == 1 and dilation == 1, \
            "ModelNew custom kernel supports stride=1, dilation=1"
        assert isinstance(kernel_size, int) and 1 <= kernel_size <= 7

        self.in_channels = int(in_channels)
        self.out_channels = int(out_channels)
        self.kernel_size = int(kernel_size)
        self.stride = int(stride)
        self.padding = int(padding)
        self.dilation = int(dilation)
        self.groups = int(groups)

        K = self.kernel_size
        self.weight = nn.Parameter(
            torch.empty(self.out_channels, self.in_channels, K, K))
        if bias:
            self.bias = nn.Parameter(torch.empty(self.out_channels))
        else:
            self.register_parameter("bias", None)

        self.reset_parameters()
        self._ext = conv2d_ext

    def reset_parameters(self):
        nn.init.kaiming_uniform_(self.weight, a=math.sqrt(5))
        if self.bias is not None:
            fan_in = self.in_channels * self.kernel_size * self.kernel_size
            bound = 1.0 / math.sqrt(fan_in) if fan_in > 0 else 0.0
            nn.init.uniform_(self.bias, -bound, bound)

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        return self._ext.conv2d_cute_forward(
            x,
            self.weight,
            self.bias if self.bias is not None else None,
            self.stride,
            self.padding,
            self.dilation,
        )

