      int gic = ic0 + ic;
      int ih  = ih0 + sh;
      int iw  = iw0 + sw;
      T v = T(0);
      if (gic < C && (unsigned)ih < (unsigned)H && (unsigned)iw < (unsigned)W) {
        v = mX(gic, ih, iw);
      }
      sX(ic, sh, sw) = v;
    }
    __syncthreads();

    // Compute on the resident tiles
    #pragma unroll
    for (int ic = 0; ic < IC_C; ++ic) {
      if (ic0 + ic >= C) break;
      #pragma unroll
      for (int kh = 0; kh < K; ++kh) {
        #pragma unroll
        for (int kw = 0; kw < K; ++kw) {
          T xv[PVec];
          #pragma unroll
          for (int i = 0; i < PVec; ++i) {
            xv[i] = sX(ic, ph[i] + kh, pw[i] + kw);
          }
          #pragma unroll
          for (int o = 0; o < OC_C; ++o) {
            T wv = sW(o, ic, kh, kw);
            #pragma unroll
            for (int i = 0; i < PVec; ++i) {
              acc[o][i] += xv[i] * wv;
            }
          }
        }
      }
    }
    __syncthreads();
  }

  // Epilogue: write results
  #pragma unroll
  for (int o = 0; o < OC_C; ++o) {
    int oc = oc_base + o;
    if (oc >= OC) continue;
    #pragma unroll
    for (int i = 0; i < PVec; ++i) {
      if (!pv[i]) continue;
      mY(oc, oh0 + ph[i], ow0 + pw[i]) = acc[o][i];
    }
  }
}

namespace {
template <int K>
void conv2d_launch(const float* X, const float* Wt, const float* B, float* Y,
                   int N, int C, int H, int W, int OC, int Hout, int Wout,
                   int pad, cudaStream_t stream)
{
  constexpr int TH   = 16;
  constexpr int TW   = 32;
  constexpr int OC_C = 8;
  dim3 block(256);
  dim3 grid((unsigned)(((Hout + TH - 1) / TH) * ((Wout + TW - 1) / TW)),
            (unsigned)((OC + OC_C - 1) / OC_C),
            (unsigned)N);
  conv2d_cute_kernel<K, float><<<grid, block, 0, stream>>>(
      X, Wt, B, Y, N, C, H, W, OC, Hout, Wout, pad);
}
} // namespace

torch::Tensor conv2d_cute_forward(torch::Tensor x,
                                  torch::Tensor w,
                                  c10::optional<torch::Tensor> b,
                                  int stride, int padding, int dilation)
{
  TORCH_CHECK(x.is_cuda() && w.is_cuda(), "x and w must be CUDA tensors");
  TORCH_CHECK(x.scalar_type() == at::kFloat, "x must be float32");
  TORCH_CHECK(w.scalar_type() == at::kFloat, "w must be float32");
  TORCH_CHECK(x.dim() == 4, "x must be [N, C, H, W]");
  TORCH_CHECK(w.dim() == 4, "w must be [OC, C, K, K]");
  TORCH_CHECK(stride == 1 && dilation == 1,
              "custom CuTe kernel currently supports stride=1, dilation=1");
  TORCH_CHECK(padding >= 0, "padding must be >= 0");

  int64_t N  = x.size(0);
  int64_t C  = x.size(1);
  int64_t H  = x.size(2);
  int64_t W  = x.size(3);
  int64_t OC = w.size(0);
  int64_t K  = w.size(2);
  TORCH_CHECK(w.size(1) == C, "w.size(1) must equal C (groups=1)");
  TORCH_CHECK(w.size(3) == K, "kernel must be square");

  int64_t Hout = (H + 2 * padding - (K - 1) - 1) + 1;  // stride=1, dilation=1
  int64_t Wout = (W + 2 * padding - (K - 1) - 1) + 1;
  TORCH_CHECK(Hout > 0 && Wout > 0, "Invalid output size");

  auto x_c = x.contiguous();
  auto w_c = w.contiguous();

  torch::Tensor b_c;
  const float* b_ptr = nullptr;
  if (b.has_value()) {
    b_c = b.value().contiguous();
    TORCH_CHECK(b_c.is_cuda() && b_c.scalar_type() == at::kFloat,
                "bias must be CUDA float32");
    TORCH_CHECK(b_c.dim() == 1 && b_c.size(0) == OC, "bias must be [OC]");
    b_ptr = b_c.data_ptr<float>();
  }

  auto y = torch::empty({N, OC, Hout, Wout}, x.options());

  cudaStream_t stream = c10::cuda::getCurrentCUDAStream().stream();
  const float* Xp = x_c.data_ptr<float>();
  const float* Wp = w_c.data_ptr<float>();
  float* Yp = y.data_ptr<float>();

  switch ((int)K) {
    case 1: conv2d_launch<1>(Xp, Wp, b_ptr, Yp, (int)N, (int)C, (int)H, (int)W,
                             (int)OC, (int)Hout, (int)Wout, padding, stream); break;
    case 2: conv2d_launch<2>(Xp, Wp, b_ptr, Yp, (int)N, (int)C, (int)H, (int)W,
                             (int)OC, (int)Hout, (int)Wout, padding, stream); break;
    case 3: conv2d_launch<3>(Xp, Wp, b_ptr, Yp, (int)N, (int)C, (int)H, (int)W,
                             (int)OC, (int)Hout, (int)Wout, padding, stream); break;
    case 4: conv2d_launch<4>(Xp, Wp, b_ptr, Yp, (int)N, (int)C, (int)H, (int)W,
                             (int)OC, (int)Hout, (int)Wout, padding, stream); break;
    case 5: conv2d_launch<5>(Xp, Wp, b_ptr, Yp, (int)N, (int)C, (int)H, (int)W,
                             (int)OC, (int)Hout, (int)Wout, padding, stream); break;
    case 6: conv2d_launch<6>(Xp, Wp, b_ptr, Yp, (int)N, (int)C, (int)H, (int)W,
                             (int)OC, (int)Hout, (int)Wout, padding, stream); break;
    case 7: conv2d_launch<7>(Xp, Wp, b_ptr, Yp, (int)N, (int)C, (int)H, (int)W,
                             (int)OC, (int)Hout, (int)Wout, padding, stream); break;
    default:
      TORCH_CHECK(false, "Unsupported kernel_size for custom CuTe conv2d: ", K);
  }

  auto err = cudaGetLastError();
  TORCH_CHECK(err == cudaSuccess, "conv2d_cute_kernel launch failed: ",
              cudaGetErrorString(err));

  return y;
}
